using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;using UnityEngine.UI;
namespace CTXD.Client.Features.Social { public sealed class TeamPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;public static TeamPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("TeamPanel");go.transform.SetParent(host,false);var p=go.AddComponent<TeamPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var b=LegacyUiFactory.Panel(transform,"TeamBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.8f));_window=LegacyUiFactory.PixelPanel(b,"TeamWindow",240,95,800,500,new Color(.055f,.035f,.018f,1));}async Task Refresh(){try{var list=await _api.GetTeamsAsync();Draw(list.items??Array.Empty<TeamView>());}catch(Exception ex){_status(ex.Message);Destroy(gameObject);}}void Draw(TeamView[] teams){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"LEGION TEAM",23,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),240,12,320,35);LegacyUiFactory.PixelButton(_window,"Close",720,15,65,27,()=>Destroy(gameObject));LegacyUiFactory.PixelButton(_window,"Create",20,15,90,28,async()=>{try{await _api.CreateTeamAsync();await Refresh();}catch(Exception ex){_status(ex.Message);}});var y=65;foreach(var t in teams){LegacyUiFactory.PixelLabel(_window,t.name+"  "+t.members.Length+"/"+t.maxGenerals+" generals"+(t.inspired?"  Inspired":""),16,TextAnchor.MiddleLeft,Color.white,25,y,470,28);if(t.isOwner&&!t.inspired){var id=t.id;LegacyUiFactory.PixelButton(_window,"Inspire",515,y,100,28,async()=>{try{var c=await _api.InspireTeamAsync(id);_status("Team inspire: "+c.inspireEffect+"%");await Refresh();}catch(Exception ex){_status(ex.Message);}});}if(t.isOwner&&!t.ordered){var id=t.id;LegacyUiFactory.PixelButton(_window,"Order",625,y,90,28,async()=>{try{await _api.OrderTeamAsync(id);_status("Team order completed");await Refresh();}catch(Exception ex){_status(ex.Message);}});}y+=34;}}} }
